    pub(crate) fn compare_diagnostic_parameter_element(
        &self,
        other: &Document,
        a: &DiagnosticParameterElement,
        b: &DiagnosticParameterElement,
        path: &str,
    ) -> Result<(), String> {
        self.compare_diagnostic_abstract_parameter(other, a.base(), b.base(), path)?;
        self.compare_identifiable(other, a.identifiable(), b.identifiable(), path)?;
        if a.get_array_size() != b.get_array_size() {
            return Err(format!("{path}: ARRAY_SIZE mismatch"));
        }
        let list_a = a.get_sub_elements();
        let list_b = b.get_sub_elements();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SUB_ELEMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.diagnostic_parameter_elements.get(*x).ok_or_else(|| {
                format!("{path}.SUB_ELEMENTS[{index}]: id not found in own arena")
            })?;
            let y = other.diagnostic_parameter_elements.get(*y).ok_or_else(|| {
                format!("{path}.SUB_ELEMENTS[{index}]: id not found in other arena")
            })?;
            self.compare_diagnostic_parameter_element(
                other,
                x,
                y,
                &format!("{path}.SUB_ELEMENTS[{index}]"),
            )?;
        }
        Ok(())
    }

